import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.Buc7gXeZ.js";const h=JSON.parse('{"title":"Performance","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-table/performance.md","filePath":"dynamic-table/performance.md"}'),n={name:"dynamic-table/performance.md"};function i(l,e,d,s,c,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h1><h2 id="expected-livewire-request-behavior" tabindex="-1">Expected Livewire request behavior <a class="header-anchor" href="#expected-livewire-request-behavior" aria-label="Permalink to &quot;Expected Livewire request behavior&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interaction</th><th>Requests</th></tr></thead><tbody><tr><td>Typing in search</td><td>0 (not live — see <a href="./search">search.md</a>)</td></tr><tr><td>Submitting search</td><td>1</td></tr><tr><td>Changing N filter fields, then Apply</td><td>1 (deferred <code>wire:model</code>, applied on <code>applyFilters()</code>)</td></tr><tr><td>Clicking Clear / Clear all</td><td>1</td></tr><tr><td>Clicking a sortable header</td><td>1</td></tr><tr><td>Changing per-page</td><td>1</td></tr><tr><td>Toggling a column</td><td>1 (and one preference write)</td></tr><tr><td>Completing a column drag-drop reorder</td><td>1 (and one preference write per drop, not per pointer move)</td></tr><tr><td>Applying a saved view</td><td>1</td></tr><tr><td>Saving current state as a view</td><td>1</td></tr></tbody></table><p>Never one request per keystroke, per row, or per cell. There is exactly <strong>one Livewire component per table instance</strong> — never one component per row or per cell.</p><h2 id="query-count-expectations-no-n-1" tabindex="-1">Query-count expectations (no N+1) <a class="header-anchor" href="#query-count-expectations-no-n-1" aria-label="Permalink to &quot;Query-count expectations (no N+1)&quot;">​</a></h2><p>Query count is verified to stay <strong>constant</strong> as the row count grows, both with and without relations:</p><ul><li><code>tests/Feature/DynamicTable/QueryEngineTest.php::&#39;query count stays constant regardless of result set size (no N+1)&#39;</code> — pages 5 vs 100 rows through an eager-loaded <code>BelongsTo</code> relation, asserts identical query count.</li><li><code>tests/Feature/DynamicTable/PreferencesTest.php::&#39;preferences load once during mount...&#39;</code> — preference storage is read exactly once per request, never per row.</li><li><code>tests/Feature/DynamicTable/PerformanceRegressionTest.php</code> — simple pagination issues zero <code>count()</code> queries; standard pagination issues exactly one.</li></ul><h2 id="preventing-n-1" tabindex="-1">Preventing N+1 <a class="header-anchor" href="#preventing-n-1" aria-label="Permalink to &quot;Preventing N+1&quot;">​</a></h2><ul><li><code>applySelect()</code> builds an explicit column list, never <code>select(*)</code>.</li><li><code>applyEagerLoads()</code> calls <code>with()</code> only for relation paths behind currently visible+authorized <code>RelationColumn</code>s — a hidden or unauthorized relation column never triggers an eager load.</li><li>Relation filters/search use <code>whereHas()</code>/<code>whereRelation()</code> (exists-based, correlated subqueries) rather than joins — this also prevents duplicate parent rows from to-many relation matches.</li></ul><h2 id="column-selection" tabindex="-1">Column selection <a class="header-anchor" href="#column-selection" aria-label="Permalink to &quot;Column selection&quot;">​</a></h2><p><code>applySelect()</code> always includes the model&#39;s primary key plus every visible+authorized column&#39;s underlying field, plus the foreign key for any visible first-level <code>BelongsTo</code> relation column (so eager loading can match rows). Hidden/unauthorized columns&#39; fields are never selected.</p><h2 id="relation-eager-loading-—-current-limitation" tabindex="-1">Relation eager loading — current limitation <a class="header-anchor" href="#relation-eager-loading-—-current-limitation" aria-label="Permalink to &quot;Relation eager loading — current limitation&quot;">​</a></h2><p><code>with($paths)</code> loads the full related row, not a field-narrowed subset. This still eliminates the N+1 risk (the primary performance hazard) but is not maximally minimal payload — see <a href="./package-extraction">package-extraction.md</a> for the upgrade path if this becomes measurable.</p><h2 id="large-relation-option-lists" tabindex="-1">Large relation option lists <a class="header-anchor" href="#large-relation-option-lists" aria-label="Permalink to &quot;Large relation option lists&quot;">​</a></h2><p>See <a href="./relationships#large-relation-option-lists">relationships.md</a> — <code>BelongsToFilter::async()</code> exists as a contract; the shipped filter-panel UI does not yet implement the async search-as-you-type picker (plain numeric-ID input for now).</p><h2 id="pagination-recommendations" tabindex="-1">Pagination recommendations <a class="header-anchor" href="#pagination-recommendations" aria-label="Permalink to &quot;Pagination recommendations&quot;">​</a></h2><ul><li>Prefer <code>simplePaginate()</code> over <code>paginate()</code> when the UI doesn&#39;t need a total page count — it skips the <code>count(*)</code> query entirely.</li><li>Never call <code>-&gt;get()</code> on an unbounded table query outside pagination.</li></ul><h2 id="export-recommendations-for-when-export-is-implemented" tabindex="-1">Export recommendations (for when export is implemented) <a class="header-anchor" href="#export-recommendations-for-when-export-is-implemented" aria-label="Permalink to &quot;Export recommendations (for when export is implemented)&quot;">​</a></h2><p><code>exportable()</code> is currently a config flag only (see <a href="./columns">columns.md</a>). When an exporter is built, it must: reuse the same authorized query and authorized column set as the live table (never a separate unscoped export path), chunk large datasets, and never hydrate the full result set into memory at once.</p><h2 id="recommended-database-indexes" tabindex="-1">Recommended database indexes <a class="header-anchor" href="#recommended-database-indexes" aria-label="Permalink to &quot;Recommended database indexes&quot;">​</a></h2><p>For any real table using this engine, index:</p><ul><li>Every column marked <code>-&gt;searchable()</code></li><li>Every column/relation targeted by a <code>Filter</code></li><li>Every column marked <code>-&gt;sortable()</code></li><li>Every foreign key used by a <code>RelationColumn</code>/relation filter</li><li><code>user_table_preferences(user_id, table_key)</code> — already a unique index from the migration</li><li><code>table_views(user_id, table_key)</code> — already indexed from the migration</li></ul>',22)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
